<script>
  import { Section, Action, MapView, ask } from 'design';
  import Coffee from 'phosphor-svelte/lib/Coffee';
  import NavigationArrow from 'phosphor-svelte/lib/NavigationArrow';

  let held = $state(false);

  const places = [
    { label: 'Home', sublabel: '27 Pellory Street' },
    { label: 'Wrenhollow Coffee', sublabel: '14 Quillfeather Lane' }
  ];
</script>

<Section title="Wrenhollow Coffee" kicker="Saturday, Nov 7 · 3:00 PM">
  <MapView {places} height={200} />
  <p class="m-text">A quiet corner café with window tables and a small back room. Easy to talk, easy to linger.</p>
  <p class="m-meta">14 Quillfeather Lane · 18 min walk
Open until 6:00 PM on Saturdays</p>
  {#snippet actions()}
    <Action
      label={held ? 'Table held' : 'Hold a table for two'}
      sublabel={held ? 'Window table, 3:00 PM' : 'Free, held 15 minutes'}
      icon={Coffee}
      primary
      disabled={held}
      onclick={() => (held = true)}
    />
    <Action
      label="Directions"
      icon={NavigationArrow}
      onclick={() => ask('Walking directions from 27 Pellory Street to Wrenhollow Coffee, 14 Quillfeather Lane, 18 minutes', 'Directions')}
    />
  {/snippet}
</Section>
```

